import{_ as s,o as a,c as i,ag as n}from"./chunks/framework.CJHUtV7T.js";const t="/08C-Projet-Prog/assets/nouvelle-conn1.CkNT9ux_.png",r="/08C-Projet-Prog/assets/nouvelle-conn.D--NoO9c.png",o="/08C-Projet-Prog/assets/emplacement-bd.DC5zi9rv.png",l="/08C-Projet-Prog/assets/nouvelle-requete.DVTlU4go.png",d="/08C-Projet-Prog/assets/sql-dbeaver.Dd4ZYxP4.png",c="/08C-Projet-Prog/assets/microsoft-sqlite.79Y28TdJ.png",u="/08C-Projet-Prog/assets/copie-BD-dans-bin.CbtkFTSE.png",q=JSON.parse('{"title":"Base de données embarquée - SQLite","description":"","frontmatter":{},"headers":[],"relativePath":"ressources/sqlite.md","filePath":"ressources/sqlite.md"}'),p={name:"ressources/sqlite.md"};function h(m,e,g,b,k,v){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="base-de-donnees-embarquee-sqlite" tabindex="-1">Base de données embarquée - SQLite <a class="header-anchor" href="#base-de-donnees-embarquee-sqlite" aria-label="Permalink to &quot;Base de données embarquée - SQLite&quot;">​</a></h1><p><code>SQLite</code> est un système de gestion de base de données léger. Contrairement aux SGBD classiques tels que <code>MySQL</code> ou <code>Oracle</code>, il n&#39;a pas besoin d&#39;un serveur pour fonctionner. À la place d&#39;une base de données hébergée sur un serveur, une base de données embarquée se présente sous forme d&#39;un seul fichier.</p><h2 id="avantages" tabindex="-1">Avantages <a class="header-anchor" href="#avantages" aria-label="Permalink to &quot;Avantages&quot;">​</a></h2><ul><li>Facilité de déploiement car aucune administration : une simple manipulation d&#39;un fichier.</li><li>Multiplateforme</li><li>Très populaire : la plus utilisée dans le monde (smartphones, navigateurs ...)</li><li>Un choix idéal pour le stockage de données locales</li></ul><h2 id="inconvenient" tabindex="-1">Inconvénient <a class="header-anchor" href="#inconvenient" aria-label="Permalink to &quot;Inconvénient&quot;">​</a></h2><p>Ne convient pas dans le cas d&#39;une très forte sollicitation de la base. Exemple : un site Web avec un grand trafic et plusieurs écritures simultanées.</p><h2 id="client-sql-a-recommander-dbeaver" tabindex="-1">Client SQL à recommander : DBeaver <a class="header-anchor" href="#client-sql-a-recommander-dbeaver" aria-label="Permalink to &quot;Client SQL à recommander : DBeaver&quot;">​</a></h2><p><strong><a href="https://dbeaver.io/download/" target="_blank" rel="noreferrer">DBeaver</a></strong> est un client SQL graphique et universel. Community en est la version gratuite. Voici comment créer une base de données SQLite avec DBeaver :</p><ol><li>Créer une nouvelle connexion : <img src="'+t+'" alt="Nouvelle connexion"><br><img src="'+r+'" alt="Créer une connexion SQLite"><br></li><li>Spécifier le chemin vers son emplacement physique sur le disque puis tester la connexion. <img src="'+o+'" alt="Emplacement de la BD"><br> La base de données est un fichier avec l&#39;extension <strong>.db</strong>. Vous pouvez le créer en lui donnant un nom. Exemple : <code>mabase.db</code>.</li><li>Pour exécuter des requêtes <code>SQL</code> (insert, update, select ...) <img src="'+l+'" alt="Nouvelle requête"> <br><img src="'+d+'" alt="Éditeur de requête SQL"></li></ol><h2 id="connexion-a-partir-d-un-projet-c" tabindex="-1">Connexion à partir d&#39;un projet C# <a class="header-anchor" href="#connexion-a-partir-d-un-projet-c" aria-label="Permalink to &quot;Connexion à partir d&#39;un projet C#&quot;">​</a></h2><p>Pour interagir avec une BD <code>SQLite</code> à partir d&#39;un projet en C#, il existe plusieurs packages <code>NuGet</code> mais je vous recommande d&#39;utiliser le package officiel de Microsoft pour sa légèreté et sa popularité.</p><ol><li>Vous aurez besoin d&#39;ajouter les 2 packages suivants à votre projet :</li></ol><ul><li><a href="https://www.nuget.org/packages/Microsoft.Data.Sqlite.Core" target="_blank" rel="noreferrer">Microsoft.Data.Sqlite</a></li><li><a href="https://www.nuget.org/packages/sqlitepclraw.bundle_e_sqlite3/" target="_blank" rel="noreferrer">SQLitePCLRaw.bundle_e_sqlite3</a><img src="'+c+`" alt="Packages microsoft sqlite"><br></li></ul><ol start="2"><li>L&#39;utilisation de la librairie est très semblable à celle que vous avez utilisée en cours de Programmation Orientée Objet(<code>MySQL Connector</code>) pour vous connecter et interagir avec une base de données <code>MySQL</code>. La seule différence réside dans l&#39;importation du package et la définition de la chaîne de connexion.</li></ol><ul><li>Importation de la librairie :</li></ul><div class="language-c# vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c#</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">using</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Microsoft</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Data</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Sqlite</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><ul><li>Dans la chaîne de connexion, il suffit de spécifier le chemin relatif du fichier de base de données (contrairement à MySQL où il faut spécifier les paramètres de connexion au serveur):</li></ul><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;ConnectionStrings&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;DefaultConnection&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Data Source=Data/mabase.db&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Il faut aussi changer les propriétés du fichier <code>.db</code>pour que la BD soit copiée dans le dossier <code>bin/Debug/</code>au moment de l&#39;exécution du programme.</p><ul><li>Action de génération : Contenu.</li><li>Copier dans le répertoire de sortie : Copier si plus récent. <img src="`+u+'" alt="Copie de la bd dans le bin"><br><em>Conseil : Pour un code propre, il est recommandé de placer le fichier de base de données (.db) à l&#39;intérieur d&#39;un dossier Data se trouvant à la racine du projet.</em></li><li>Le reste des instructions (création de la connexion, préparation d&#39;une commande SQL, l&#39;exécuter ...) devraient être identiques à celles de <code>MySQL Connector</code>. Au besoin, veuillez consulter la documentation officielle de <strong><a href="https://learn.microsoft.com/en-us/dotnet/standard/data/sqlite/" target="_blank" rel="noreferrer">Microsoft Data SQLite</a></strong>.</li></ul>',20)])])}const C=s(p,[["render",h]]);export{q as __pageData,C as default};
